window.__posterData({"id": "erik-selin", "name": "Erik Selin", "folder": "AI RavePoster_2026_10_30_09_37_16", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// ---------- Grundinställningar ----------\n// Här bestämmer jag storleken på affischen\nconst CANVAS_W = 600; // bredd\nconst CANVAS_H = 800; // höjd\n\n// Gul färg som används på texterna\nconst ACCENT = \"#fbb728\";\n\n// Hur mycket cirklarna rör sig när man håller in musen\nconst WOBBLE_RADIUS = 8;    // hur långt de rör sig (i pixlar)\nconst WOBBLE_SPEED = 0.03;  // hur snabbt de rör sig (lägre = långsammare)\nconst COLOR_INTERVAL = 10;  // hur ofta färgerna byter (högre = långsammare)\n\n// Hur ringarna (ripples) beter sig när man klickar\nconst RIPPLE_SPEED = 4;     // hur snabbt ringen växer\nconst RIPPLE_FADE = 4;      // hur snabbt ringen försvinner\n\n// Cirklarnas vanliga färger\nconst colors = [\"#e0cba3\", \"#C9362B\", \"#171717\", \"#D9AD36\", \"#0000a0\"];\n// Färger som används när man klickar\nconst clickColors = [\"#5221d3\", \"#171717\", \"#80ff80\", \"#ff17d7\", \"#f4fe38\"];\n\n// Variabler som programmet kommer ihåg medan det körs\nlet img;                      // bakgrundsbilden\nlet wobble = 0;               // 0 = cirklarna står still, 1 = de rör sig som mest\nlet randomColors = [...colors]; // cirklarnas slumpade färger\nlet ripples = [];             // lista med alla ringar som syns just nu\n\n// ---------- Start ----------\n// Körs en gång när sidan startar\nasync function setup() {\n  createCanvas(CANVAS_W, CANVAS_H); // skapar affischen\n  img = await loadImage(\"posterbak.jpg\"); // hämtar bakgrundsbilden\n}\n\n// ---------- Hjälpfunktioner ----------\n// Skriver ut en text med gul färg och fet stil\nfunction drawLabel(str, x, y, size, alignH, alignV) {\n  push(); // börjar en egen \"grupp\" så inställningarna inte påverkar resten\n  fill(ACCENT);       // gul färg\n  textSize(size);     // storlek på texten\n  textStyle(BOLD);    // fet text\n  if (alignH !== undefined) textAlign(alignH, alignV); // var texten börjar\n  text(str, x, y);    // skriver ut texten\n  pop(); // avslutar gruppen\n}\n\n// Ger varje cirkel en ny slumpad färg\nfunction pickRandomColors() {\n  randomColors = colors.map(() => random(clickColors));\n}\n\n// Körs automatiskt varje gång man trycker ner musen\nfunction mousePressed() {\n  pickRandomColors(); // cirklarna får nya färger\n\n  // Skapar en ny ring där man klickade\n  ripples.push({\n    x: mouseX,                 // var ringen börjar (sidled)\n    y: mouseY,                 // var ringen börjar (höjdled)\n    r: 0,                      // storlek, börjar på noll\n    alpha: 255,                // 255 = syns helt, 0 = osynlig\n    col: random(clickColors),  // slumpad färg\n  });\n}\n\n// ---------- Rita cirklarna ----------\nfunction drawCircles() {\n  // Gör rörelsen mjuk: startar långsamt när man klickar\n  // och går långsamt tillbaka när man släpper\n  wobble = lerp(wobble, mouseIsPressed ? 1 : 0, 0.1);\n\n  // Byter färger med jämna mellanrum när man håller in musen\n  if (mouseIsPressed && frameCount % COLOR_INTERVAL === 0) {\n    pickRandomColors();\n  }\n\n  // Väljer vilka färger som ska användas just nu\n  const palette = mouseIsPressed ? randomColors : colors;\n\n  // Upprepar samma sak för alla fem cirklar\n  for (let i = 0; i < palette.length; i++) {\n    // Räknar ut hur cirkeln ska röra sig i en liten ring\n    const angle = frameCount * WOBBLE_SPEED + i * 0.8;\n    const offsetX = cos(angle) * WOBBLE_RADIUS * wobble; // flyttar i sidled\n    const offsetY = sin(angle) * WOBBLE_RADIUS * wobble; // flyttar uppåt/nedåt\n\n    fill(palette[i]); // väljer cirkelns färg\n    ellipse(200 + i * 50 + offsetX, 240 + offsetY, 90); // ritar cirkeln\n  }\n}\n\n// ---------- Rita ringarna ----------\nfunction drawRipples() {\n  push();\n  noFill();        // ringarna är tomma inuti\n  strokeWeight(4); // hur tjock linjen är\n\n  // Går igenom alla ringar, från den sista till den första\n  for (let i = ripples.length - 1; i >= 0; i--) {\n    const rp = ripples[i];\n\n    // Gör färgen mer genomskinlig för varje bildruta\n    const c = color(rp.col);\n    c.setAlpha(rp.alpha);\n    stroke(c);\n\n    ellipse(rp.x, rp.y, rp.r * 2);   // stora ringen\n    ellipse(rp.x, rp.y, rp.r * 1.2); // lilla ringen inuti\n\n    rp.r += RIPPLE_SPEED;    // ringen växer lite\n    rp.alpha -= RIPPLE_FADE; // ringen blir lite mer osynlig\n\n    // När ringen är helt osynlig tas den bort\n    if (rp.alpha <= 0) ripples.splice(i, 1);\n  }\n\n  pop();\n}\n\n// ---------- Huvudloop ----------\n// Körs om och om igen, ungefär 60 gånger varje sekund\nfunction draw() {\n  background(0);                        // svart bakgrund (täcks av bilden)\n  image(img, 0, 0, CANVAS_W, CANVAS_H); // ritar bakgrundsbilden\n\n  drawLabel(\"Erik Selin\", 10, 10, 18, LEFT, TOP); // namnet uppe till vänster\n  drawCircles();                                  // de fem cirklarna\n  drawRipples();                                  // ringarna när man klickar\n  drawLabel(\"VIBEZ\", 450, 790, 48);               // titeln nere till höger\n}\n\n\n//Till skillnad från min gamla kod så har den ändrat en hel del och lagt till flera nya Constants som jag inte har lärt mig än.\n//den har även lagt till flera nya rader som jag anser har gjort koden mycket svårare att förstå.\n//Jag bad Claude att lägga till kommentarer i koden för att försöka förstå vad den gjorde men det gjorde att koden blev svårare att läsa och fick snarare motsatt effekt ", "assets": {"posterbak.jpg": {"mime": "image/webp", "b64": ""}}});
